using System;
using System.Collections.Generic;
using System.IO;
using System.Text;
using System.Threading;

namespace Common.gamestate;

public class GameLog
{
	private Queue<string> logs = new Queue<string>();

	private bool isInit;

	private string path;

	private string filePath;

	private Thread thread;

	private bool isRunning;

	private int writeFailures;

	private static GameLog gameLog = new GameLog();

	public void InitInternal(string path)
	{
		try
		{
			DateTime now = DateTime.Now;
			filePath = Path.Combine(path, "log_" + now.ToString("yyyy_MM_dd_") + ((int)now.TimeOfDay.TotalSeconds).ToString("00000") + ".log");
			Directory.CreateDirectory(path);
			this.path = path;
			string[] files = Directory.GetFiles(path, "log_*.log", SearchOption.TopDirectoryOnly);
			if (files.Length > 4)
			{
				Array.Sort(files);
				for (int num = files.Length; num > 4; num--)
				{
					File.Delete(files[files.Length - num]);
				}
			}
			File.Create(filePath);
			isInit = true;
			thread = new Thread(LogProc);
			StartLogging();
		}
		catch (Exception ex)
		{
			Console.WriteLine("Log init failure: " + ex.Message, false);
		}
		isInit = true;
		isRunning = true;
	}

	public void StartLogging()
	{
		if (isInit && !isRunning)
		{
			isRunning = true;
			thread.Start();
		}
	}

	public void StopLogging()
	{
		isRunning = false;
	}

	public void LogProc()
	{
		while (isRunning)
		{
			if (logs.Count > 0)
			{
				WriteLogsToFile();
			}
			Thread.Sleep(1000);
		}
	}

	public void WriteLogsToFile()
	{
		StringBuilder stringBuilder = new StringBuilder();
		lock (logs)
		{
			while (logs.Count > 0)
			{
				stringBuilder.AppendLine(logs.Dequeue());
			}
		}
		try
		{
			File.AppendAllText(filePath, stringBuilder.ToString());
			writeFailures = 0;
		}
		catch (Exception ex)
		{
			Console.WriteLine("Log write failure: " + ex.Message, false);
			writeFailures++;
			if (writeFailures >= 3)
			{
				Console.WriteLine("Too many log write failures. Stopping logging.", false);
				isRunning = false;
			}
		}
	}

	public void WriteLogInternal(string log)
	{
		lock (logs)
		{
			logs.Enqueue("[" + DateTime.Now.ToLongTimeString() + "] " + log);
		}
	}

	public static void Init(string path)
	{
		gameLog.InitInternal(path);
	}

	public static void Stop()
	{
		gameLog.StopLogging();
	}

	public static void WriteLog(string log)
	{
		if (gameLog.isInit && gameLog.isRunning)
		{
			gameLog.WriteLogInternal(log);
		}
	}

	public static List<string> GetAllLogsDump()
	{
		List<string> list = new List<string>(1000);
		if (gameLog.isInit)
		{
			string[] files = Directory.GetFiles(gameLog.path, "*.log", SearchOption.TopDirectoryOnly);
			Array.Sort(files);
			Array.Reverse(files);
			for (int i = 0; i < files.Length; i++)
			{
				try
				{
					list.Add("");
					list.Add("=");
					list.Add(Path.GetFileName(files[i]));
					list.Add("=");
					string[] array = File.ReadAllLines(files[i]);
					Array.Reverse(array);
					list.AddRange(array);
				}
				catch (Exception ex)
				{
					list.Add(ex.Message);
					Console.WriteLine(ex.Message, false);
				}
			}
		}
		return list;
	}

	public static void OnExiting()
	{
		if (gameLog.isInit && gameLog.isRunning)
		{
			Stop();
			gameLog.WriteLogsToFile();
		}
	}
}
using System;
using Microsoft.Xna.Framework;
using Microsoft.Xna.Framework.Graphics;

namespace MapEdit;

public class ScrollManager
{
	public static float zoom = 1f;

	public static Vector2 totalScreenSize;

	public static Vector2 screenSize;

	public static Vector2 halfScreenSize;

	public static Vector2 scroll;

	private static Matrix projectionMatrix;

	private static GraphicsDevice dev;

	public const int DEPTH_ONE = 0;

	public const int DEPTH_ZERO = 1;

	public const int DEPTH_MINUS_ONE = 2;

	public const int DEPTH_MINUS_TWO = 3;

	public const int DEPTH_MINUS_FOUR = 4;

	public const int DEPTH_TWO = 5;

	public const int DEPTH_FOUR = 6;

	public const int DEPTH_EIGHT = 7;

	public const int DEPTH_TWELVE = 8;

	public const int DEPTH_TWENTY = 9;

	public static float[] cannedDepth;

	public static Vector2 tL;

	public static Vector2 bR;

	public static float candleAlpha;

	public static void Init(GraphicsDevice _dev, Vector2 _screenSize)
	{
		dev = _dev;
		SetProjectionMatrix((float)Math.PI / 4f);
		screenSize = _screenSize;
		zoom = -10f;
		scroll = default;
		cannedDepth = new float[14];
	}

	public static void UpdateCannedValues()
	{
		cannedDepth[0] = GetCannedSize(1f);
		cannedDepth[1] = GetCannedSize(0f);
		cannedDepth[2] = GetCannedSize(-1f);
		cannedDepth[5] = GetCannedSize(2f);
		cannedDepth[7] = GetCannedSize(8f);
		cannedDepth[6] = GetCannedSize(4f);
		cannedDepth[8] = GetCannedSize(12f);
		cannedDepth[9] = GetCannedSize(20f);
		cannedDepth[3] = GetCannedSize(-2f);
		cannedDepth[4] = GetCannedSize(-4f);
		halfScreenSize = screenSize / 2f;
	}

	public static void SetProjectionMatrix(float fov)
	{
		projectionMatrix = Matrix.CreatePerspectiveFieldOfView(fov, dev.Viewport.AspectRatio, 0.3f, 1000f);
	}

	private static float GetCannedSize(float dist)
	{
		Matrix view = Matrix.CreateLookAt(new Vector3(zoom, 0f, 0f), new Vector3(dist, 0f, 0f), new Vector3(0f, 1f, 0f));
		Vector3 vector = dev.Viewport.Project(new Vector3(dist, 0f, 0f), projectionMatrix, view, Matrix.Identity);
		return dev.Viewport.Project(new Vector3(dist, 0f, 0.01f), projectionMatrix, view, Matrix.Identity).X - vector.X;
	}

	public static float GetSize(float dist)
	{
		if (dist == 0f)
		{
			return cannedDepth[1];
		}
		if (dist > 0f)
		{
			if (dist <= 1f)
			{
				return cannedDepth[0];
			}
			if (dist <= 2f)
			{
				return cannedDepth[5];
			}
			if (dist <= 4f)
			{
				return cannedDepth[6];
			}
			if (dist <= 8f)
			{
				return cannedDepth[7];
			}
			if (dist <= 12f)
			{
				return cannedDepth[8];
			}
			return cannedDepth[9];
		}
		if (dist < 0f)
		{
			if (dist >= -1f)
			{
				return cannedDepth[2];
			}
			if (dist >= -2f)
			{
				return cannedDepth[3];
			}
			if (dist >= -4f)
			{
				return cannedDepth[4];
			}
		}
		Matrix view = Matrix.CreateLookAt(new Vector3(zoom, 0f, 0f), new Vector3(dist, 0f, 0f), new Vector3(0f, 1f, 0f));
		Vector3 vector = dev.Viewport.Project(new Vector3(dist, 0f, 0f), projectionMatrix, view, Matrix.Identity);
		return dev.Viewport.Project(new Vector3(dist, 0f, 0.01f), projectionMatrix, view, Matrix.Identity).X - vector.X;
	}

	public static Vector2 GetRealLoc(Vector2 loc, float layer)
	{
		return (loc - halfScreenSize) / GetSize(layer) + scroll;
	}

	public static Vector2 GetScreenLoc(Vector2 loc, float layer)
	{
		if (layer == 1f)
		{
			return GetScreenLoc(loc, 0);
		}
		if (layer == -1f)
		{
			return GetScreenLoc(loc, 2);
		}
		if (layer == 0f)
		{
			return GetScreenLoc(loc, 1);
		}
		if (layer == 2f)
		{
			return GetScreenLoc(loc, 5);
		}
		if (layer == 4f)
		{
			return GetScreenLoc(loc, 6);
		}
		if (layer == 8f)
		{
			return GetScreenLoc(loc, 7);
		}
		if (layer == 12f)
		{
			return GetScreenLoc(loc, 8);
		}
		if (layer == 20f)
		{
			return GetScreenLoc(loc, 9);
		}
		if (layer == -2f)
		{
			return GetScreenLoc(loc, 3);
		}
		if (layer == -4f)
		{
			return GetScreenLoc(loc, 4);
		}
		return (loc - scroll) * GetSize(layer) + halfScreenSize;
	}

	public static Vector2 GetScreenLoc(Vector3 loc, float layer)
	{
		return (new Vector2(loc.X, loc.Y - loc.Z) - scroll) * GetSize(layer) + halfScreenSize;
	}

	public static Vector2 GetScreenLoc(Vector2 loc, int layer)
	{
		return (loc - scroll) * cannedDepth[layer] + halfScreenSize;
	}

	public static Vector2 GetScreenLoc(Vector3 loc, int layer)
	{
		return (new Vector2(loc.X, loc.Y - loc.Z) - scroll) * cannedDepth[layer] + halfScreenSize;
	}

	internal static void Reset()
	{
		scroll = default;
		zoom = -10f;
	}

	public static float GetHdFactor()
	{
		if (!(screenSize.Y > 1080f))
		{
			return 1f;
		}
		return screenSize.Y / 1080f;
	}
}
