using System;
using System.IO;
using System.Windows.Forms;
using Common.gamestate;
using ProjectTower.steam;

namespace ProjectTower;

internal static class Program
{
	private static void Main(string[] args)
	{
		Environment.SetEnvironmentVariable("FNA_PLATFORM_BACKEND", "SDL3");
		SteamServiceMgr.Init();
		GameLog.Init(GetLogDir());
		GameLog.WriteLog("Logs Started");
		GameLog.GetAllLogsDump();
		using (Game1 game = new Game1())
		{
			AppDomain.CurrentDomain.UnhandledException += UnhandledExceptionTrapper;
			game.Run();
		}
		GameLog.WriteLog("Program Ended");
		GameLog.GetAllLogsDump();
		GameLog.OnExiting();
	}

	private static string GetLogDir()
	{
		return Path.Combine(Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.Personal), "Salt and Sanctuary"), "logs");
	}

	private static void UnhandledExceptionTrapper(object sender, UnhandledExceptionEventArgs e)
	{
		string logDir = GetLogDir();
		if (!Directory.Exists(logDir))
		{
			Directory.CreateDirectory(logDir);
		}
		BinaryWriter binaryWriter = new BinaryWriter(File.Open(Path.Combine(logDir, "crash.log"), FileMode.OpenOrCreate));
		binaryWriter.Write(e.ExceptionObject.ToString());
		binaryWriter.Close();
		Game1.needsQuit = true;
		MessageBox.Show("Sorry, an error occurred.\n\nPlease submit the following report to the Ska Studios discord: discord.gg/skastudios, so we can keep improving Salt and Sanctuary:\n\n" + e.ExceptionObject.ToString(), "Error", MessageBoxButtons.OK, MessageBoxIcon.Hand);
	}
}
using Microsoft.Xna.Framework;
using ProjectTower.character;
using ProjectTower.config;
using ProjectTower.gamestate;
