	public static float frameTime;

	public static float realTime;

	public static long updateTicks;

	public static bool needsQuit;

	public static CharSaveList charSaveList;

	public static float slowTime;

	public static int language;

	public static int needsBorderChange;

	private static double logicalFrameVal;

	private static bool updateThisFrame;

	public static Game1 game;

	public Game1()
	{
		GameLog.WriteLog("Start graphics device manager...");
		graphics = new GraphicsDeviceManager(this);
		graphics.GraphicsProfile = GraphicsProfile.HiDef;
		GameLog.WriteLog("Graphics device manager::Complete");
		Content.RootDirectory = "Content";
	}

	protected override void Initialize()
	{
		ScriptCommandParser.Init();
		Rand.rand = new Random();
		IsFixedTimeStep = true;
		ConfigMgr.displayWidth = 1920;
