	public static void SetResolution(int width, int height, int fullScreen, bool vsync, int framerate)
	{
		GameLog.WriteLog("Starting new Video Settings...");
		float num = 0f;
		bool flag = false;
		while (num <= 5000f)
		{
			try
			{
				int height2 = GraphicsAdapter.DefaultAdapter.CurrentDisplayMode.Height;
				int width2 = GraphicsAdapter.DefaultAdapter.CurrentDisplayMode.Width;
				bool flag2 = fullScreen == 2;
				if ((height2 < height) | flag2)
				{
					height = height2;
				}
				if ((width2 < width) | flag2)
				{
					width = width2;
				}
				ScrollManager.totalScreenSize = new Vector2(width, height);
				ScrollManager.screenSize = ScrollManager.totalScreenSize;
				if (GameStateManager.coopPlayerIdx > -1 && GameStateManager.splitScreenCoopMode)
				{
					ScrollManager.screenSize.X /= 2f;
				}
				graphics.PreferredBackBufferWidth = (int)ScrollManager.totalScreenSize.X;
				graphics.PreferredBackBufferHeight = (int)ScrollManager.totalScreenSize.Y;
				switch (fullScreen)
				{
				case 0:
					graphics.IsFullScreen = false;
					graphics.HardwareModeSwitch = true;
					break;
				case 1:
					graphics.IsFullScreen = true;
					graphics.HardwareModeSwitch = true;
					break;
				case 2:
					graphics.IsFullScreen = true;
					graphics.HardwareModeSwitch = false;
					break;
				}
				CreateTargs();
				game.TargetElapsedTime = TimeSpan.FromTicks(10000000L / (long)framerate);
				graphics.SynchronizeWithVerticalRetrace = vsync;
				graphics.ApplyChanges();
				ScrollManager.Init(graphics.GraphicsDevice, ScrollManager.screenSize);
				GameLog.WriteLog("Resolution Change:: Complete");
				GameLog.GetAllLogsDump();
				break;
			}
			catch (Exception ex)
			{
				int num2 = 50;
				num += (float)num2;
				if (num >= 5000f)
				{
					GameLog.WriteLog("Video Settings Change:: Wait time exceeded. Cannot apply changes.");
					GameLog.GetAllLogsDump();
					if (flag || fullScreen != 1)
					{
						throw ex;
					}
					flag = true;
					num = 0f;
					ConfigMgr.fullScreen = 2;
					fullScreen = 1;
				}
				else
				{
					Thread.Sleep(num2);
				}
			}
		}
	}

