	private static GameTime CheckLogicalFPS(GameTime gameTime)
	{
		double num = 1.0 / 60.0;
		logicalFrameVal += gameTime.ElapsedGameTime.TotalSeconds;
		long value = (long)(num * 10000000.0);
		updateThisFrame = false;
		if (logicalFrameVal > num)
		{
			logicalFrameVal -= num;
			updateThisFrame = true;
		}
		return new GameTime(gameTime.TotalGameTime, TimeSpan.FromTicks(value), gameTime.IsRunningSlowly);
	}

