	public static Vector2 GetLobVec(Vector2 orig, Vector2 goal, float speed, float lift, float gravity, float minY)
	{
		return GetLobVec(orig, goal, speed, lift, gravity, minY, null);
	}

	public static Vector2 GetLobVec(Vector2 orig, Vector2 goal, float speed, float lift, float gravity, float minY, Map map)
	{
		Vector2 vector = (goal - orig) * 0.1f * speed;
		int layer = CharCols.GetLayer(orig + new Vector2(0f, -4f));
		Vector2 result = default;
		float num = -1f;
		Vector2 vector2 = vector;
		for (int i = 0; i < 14; i++)
		{
			bool flag = false;
			Vector2 vector3 = orig;
			Vector2 vector4 = vector2;
			float num2 = -1f;
			for (int j = 0; j < 100; j++)
			{
				Vector2 vector5 = vector3;
				vector3 += vector4 * (1f / 60f);
				vector4.Y += gravity * (1f / 60f);
				if (map != null)
				{
					Vector2 vector6 = vector3 - vector5;
					int num3 = 1;
					if (vector6.X < 0f)
					{
						vector6.X = 0f - vector6.X;
					}
					if (vector6.Y < 0f)
					{
						vector6.Y = 0f - vector6.Y;
					}
					if (vector6.X > vector6.Y)
					{
						vector6.Y = vector6.X;
					}
					num3 = (int)(vector6.Y / 30f) + 1;
					_ = 1;
					for (int k = 0; k < num3; k++)
					{
						Vector2 vector7 = vector5 + (vector3 - vector5) * ((float)(k + 1) / (float)num3);
						int num4 = (int)(vector7.X / 64f);
						int num5 = (int)(vector7.Y / 32f);
						if (num4 > 0 && num5 > 0 && num4 < map.xUnits && num5 < map.yUnits)
						{
							int col = map.col[num4, num5].col;
							if ((uint)(col - 1) <= 2u)
							{
								flag = true;
							}
							if (map.col[num4, num5].layer != layer)
							{
								flag = true;
							}
						}
						if (flag)
						{
							break;
						}
					}
					if (flag)
					{
						break;
					}
				}
				if (flag)
				{
					continue;
				}
				float num6 = Math.Abs(vector3.X - goal.X) + Math.Abs(vector3.Y - goal.Y);
				if ((map != null && vector3.Y > goal.Y) || (!(num6 < num2) && !(num2 < 0f)))
				{
					continue;
				}
				if (map != null)
				{
					if (((vector5.X < goal.X && vector3.X >= goal.X) || (vector5.X > goal.X && vector3.X <= goal.X)) && vector3.Y < goal.Y)
					{
						return vector2;
					}
				}
				else
				{
					num2 = num6;
				}
			}
			if (num < 0f || num2 < num)
			{
				num = num2;
				result = vector2;
			}
			vector2.Y -= lift;
			if (vector2.Y < minY)
			{
				vector2.Y = minY;
			}
		}
		return result;
	}

	public static float GetAngle(Vector2 v1, Vector2 v2)
	{
		float num = (float)Math.PI;
		Vector2 vector = new Vector2(v2.X - v1.X, v2.Y - v1.Y);
		if (vector.X == 0f)
		{
			if (vector.Y < 0f)
			{
				return num * 0.5f;
			}
			if (vector.Y > 0f)
			{
				return num * 1.5f;
			}
		}
		if (vector.Y == 0f)
		{
			if (vector.X < 0f)
			{
				return 0f;
			}
			if (vector.X > 0f)
			{
				return num;
			}
		}
		float num2 = (float)Math.Atan(Math.Abs(vector.Y) / Math.Abs(vector.X));
		if (vector.X < 0f || vector.Y > 0f)
		{
			num2 = num - num2;
		}
		if (vector.X < 0f || vector.Y < 0f)
		{
			num2 = num + num2;
		}
		if (vector.X > 0f || vector.Y < 0f)
		{
			num2 = num * 2f - num2;
		}
		if (num2 < 0f)
		{
			num2 += num * 2f;
		}
		return num2;
	}

	public static float GetCosProg(float p)
	{
		return (float)Math.Cos(p * 3.14159f) * -0.5f + 0.5f;
	}
}

