public class GuideDoor : BaseParticle
{
	public override void Init(Particle p, Vector2 loc, Vector2 traj, float size, float rotation, int flags, int owner)
	{
		p.frame = 5f;
		p.size = size;
		p.loc = loc;
		p.traj = traj;
		Sound.Play3DSound("guidedoor", p.loc, 0);
		p.owner = owner;
		base.Init(p, loc, traj, size, rotation, flags, owner);
	}

	public override void Update(Particle p, float frameTime)
	{
		float frame = p.frame;
		base.Update(p, frameTime);
		if (!p.exists)
		{
			return;
		}
		if (frame > 3f && p.frame <= 3f)
		{
			Sound.Play3DSound("door", p.loc, 0);
		}
		if (frame > 3f && p.frame <= 3f)
		{
			Sound.Play3DSound("doorclick", p.loc, 0);
		}
		if ((int)(frame * 60f) != (int)(p.frame * 60f))
		{
			for (int i = 0; i < 2; i++)
			{
				float num = (5f - p.frame) * 500f;
				if (num > 50f)
				{
					num = 50f;
				}
				num *= ((i == 0) ? (-1f) : 1f);
				ParticleManager.AddBackAdditiveParticle(171, p.loc + new Vector2(0f, -170f) + Rand.GetRandomVec2(0f, num, 0f, 0f), default, Rand.GetRandomFloat(0.1f, 0.5f), 0f, -1, -1);
				if (!(p.frame < 4.9f))
				{
					continue;
				}
				for (int j = 0; j < 2; j++)
				{
					float num2 = (4.9f - p.frame) * 500f;
					if (num2 > 170f)
					{
						num2 = 170f;
					}
					ParticleManager.AddBackAdditiveParticle(171, p.loc + new Vector2(num, -170f) + Rand.GetRandomVec2(0f, 0f, 0f, num2), default, Rand.GetRandomFloat(0.1f, 0.5f), 0f, -1, -1);
				}
			}
		}
		if (p.frame < 2f)
		{
			p.exists = false;
		}
	}

	public override void Draw(Particle p, float brite)
	{
		if (p.frame < 4.4f)
		{
			Vector2 screenLoc = ScrollManager.GetScreenLoc(p.loc + new Vector2(-50f, -170f), 0);
			Vector2 scale = new Vector2(100f, 170f) * ScrollManager.cannedDepth[0];
			Color color = new Color(1f, 1f, 1f, 1f);
			if (p.frame < 4f)
			{
				color = new Color(0f, 0f, 0f, 1f);
				SpriteTools.sprite.Draw(Game1.nullTex, screenLoc, new Rectangle(0, 0, 1, 1), color, 0f, default, scale, SpriteEffects.None, 1f);
				float num = 1f;
				Vector2 scale2 = new Vector2(1f, 1f) * ScrollManager.cannedDepth[0];
				if (p.frame < 3f)
				{
					float num2 = 3f - p.frame;
					if (num2 > 1.7f)
					{
						num2 = 1.7f;
					}
					float num3 = (float)Math.Sin(num2);
					scale2.X -= num3;
					num -= num3;
				}
				Textures.tex[ParticleManager.spritesTexIdx].Draw(screenLoc, 161, scale2, 0f, num, num, num, 1f);
			}
			if (p.frame > 4f)
			{
				color = new Color(1f, 1f, 1f, (4.4f - p.frame) / 0.4f);
			}
			else if (p.frame > 3.5f)
			{
				color = new Color(1f, 1f, 1f, 1f);
			}
			else
			{
				color = ((!(p.frame > 3f)) ? new Color(1f, 1f, 1f, 0f) : new Color(1f, 1f, 1f, (p.frame - 3f) / 0.5f));
			}
			SpriteTools.sprite.Draw(Game1.nullTex, screenLoc, new Rectangle(0, 0, 1, 1), color, 0f, default, scale, SpriteEffects.None, 1f);
		}
		base.Draw(p, brite);
	}
}
