						return new Point(0, i);
					}
					if (MonsterCatalog.catalog[character.monsterIdx].flags == 3)
					{
						return new Point(0, i);
					}
				}
				continue;
			}
			}
			if (monsterDef.type == 2 || monsterDef.type == 3 || monsterDef.type == 5 || monsterDef.type == 6 || monsterDef.type == 4)
			{
				continue;
			}
			bool flag2 = false;
