	private Point CheckOpenChest(Character c, Character other, MonsterDef mDef, float w, int i)
	{
		int num = 1;
		int num2 = 0;
		if (mDef.type == 8)
		{
			num = 0;
			num2 = 1;
		}
		if (c.loc.Y < other.loc.Y + 32f && c.loc.Y > other.loc.Y - 64f)
		{
			bool flag = false;
			if (c.loc.X < other.loc.X)
			{
				if ((other.face == num || mDef.flags == 4) && other.loc.X < c.loc.X + w)
				{
					flag = true;
				}
			}
			else if ((other.face == num2 || mDef.flags == 4) && other.loc.X > c.loc.X - w)
			{
				flag = true;
			}
			if (flag && other.anim.animName == "chest")
			{
				return new Point(1, i);
			}
		}
		return new Point(-1, -1);
	}

	internal void Draw()
	{
		if (messageFrame > 0f && message != null)
		{
			float hdFactor = ScrollManager.GetHdFactor();
			float num = 1f;
			if (messageFrame < 0.5f)
			{
				num = messageFrame * 2f;
			}
			else
			{
				num = ((!(messageFrame < 2.5f)) ? ((3f - messageFrame) * 2f) : 1f);
			}
			Rectangle textRect = Prompt.GetTextRect(p, message);
			textRect.Y -= (int)(100f * hdFactor);
			InterfaceRender.DrawRect(textRect, num * 0.7f, 4);
			Text.DrawText(message, new Vector2(textRect.Center.X, textRect.Center.Y), new Color(1f, 1f, 1f, num), 0.55f * hdFactor, 1, p, 2);
		}
		for (int i = 0; i < prompt.Length; i++)
		{
			if (prompt[i].alpha > 0f)
			{
				prompt[i].Draw(p);
